const $=id=>document.getElementById(id);
const categories={telemetry:['Telemetry','Movement, units, vehicles and combat samples.'],stats:['Player statistics','Latest cumulative player totals. Revisions are not added together.'],session:['Session events','Joins, departures and recorded mission events.'],history:['Mission & server','Mission outcome, phases and sampled server performance.']};
let stream='telemetry',offset=0,nextOffset=null,selected=null,summary=null,pane='records',cursor=null,generation=0,listGeneration=0,recordGeneration=0;
const human=s=>s.replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const node=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
async function get(url,options={}){const r=await fetch(url,{cache:'no-store',...options});if(!r.ok){let text=`Request failed (${r.status}).`;try{text=(await r.json()).error||text;}catch{}throw Error(text);}return r.json();}
async function mutate(url,method,body){const {token}=await get('/api/auth/csrf');return get(url,{method,headers:{'X-CSRF-TOKEN':token,'Content-Type':'application/octet-stream'},body});}
function table(headers,rows){const t=node('table'),head=node('thead'),tr=node('tr');headers.forEach(h=>tr.append(node('th',h)));head.append(tr);t.append(head);const b=node('tbody');for(const row of rows){const r=node('tr');for(const value of row){const c=node('td');value instanceof Node?c.append(value):c.textContent=value??'—';r.append(c);}b.append(r);}t.append(b);return t;}
function button(label,fn){const b=node('button',label);b.type='button';b.onclick=fn;return b;}
function fields(value){if(value===null||value===undefined)return node('span','Not recorded');if(typeof value!=='object')return node('span',String(value));const dl=node('dl');for(const [key,v]of Object.entries(value)){dl.append(node('dt',human(key)));const dd=node('dd');if(v&&typeof v==='object'){const d=node('details');d.append(node('summary',Array.isArray(v)?`${v.length} items`:'View fields'),fields(v));dd.append(d);}else dd.textContent=v===null?'Not recorded':String(v);dl.append(dd);}return dl;}
function expandable(value){const d=node('details');d.append(node('summary','Details'),fields(value));return d;}
function datasetRoute(){return `/api/admin/explorer/${selected.serverId}/${stream}/${selected.id}`;}
function missionRoute(){return `/api/admin/missions/${selected.serverId}/${selected.id}`;}
function time(ms){return `${(ms/1000).toFixed(1)} s`;}
function bytes(n){return n>=1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.ceil(n/1024)} KB`;}
async function overview(){try{const d=await get('/api/admin/data');for(const [key,[name]]of Object.entries(categories)){const rows=d.streams.filter(r=>r.stream===key),count=rows.reduce((n,r)=>n+r.batches,0),problems=rows.filter(r=>['failed','rejected'].includes(r.status)).reduce((n,r)=>n+r.batches,0);$(`count-${key}`).textContent=count?`${count} batches${problems?` · ${problems} need attention`:''}`:'Not received';}$('overviewStatus').textContent='';}catch(e){$('overviewStatus').textContent=e.message;}}
async function list(){const version=++listGeneration;$('listStatus').textContent='Loading…';$('datasets').replaceChildren();$('nextData').disabled=$('prevData').disabled=true;try{const d=await get(`/api/admin/explorer?stream=${stream}&offset=${offset}&search=${encodeURIComponent($('dataSearch').value)}`);if(version!==listGeneration)return;nextOffset=d.nextOffset;$('datasets').append(table(['Map / dataset','Received','Batches','Size','Processing',''],d.rows.map(r=>[r.world.split('/').pop()||r.id,new Date(r.received).toLocaleString(),r.batches,bytes(r.bytes),r.problems?`${r.problems} need attention`:r.pending?`${r.pending} pending`:'Processed',button('Open',()=>open(r))])));$('listStatus').textContent=d.rows.length?`${offset+1}–${offset+d.rows.length} datasets`:'No datasets found.';$('nextData').disabled=nextOffset===null;$('prevData').disabled=offset===0;}catch(e){if(version===listGeneration)$('listStatus').textContent=e.message;}}
async function open(row){selected=row;summary=null;const version=++generation;++recordGeneration;pane='records';cursor=null;$('datasetDetail').hidden=false;$('detailTitle').textContent=categories[stream][0];$('detailIdentity').textContent=`${row.world||'World not processed'} · ${row.id} · Server ${row.serverId}`;if(stream!=='telemetry'){const session=node('a','View session');session.href='/sessions/'+encodeURIComponent(row.serverId)+'/'+encodeURIComponent(row.id);$('detailIdentity').append(' · ',session)};$('detailStatus').textContent='Loading coverage…';$('recordStatus').textContent='Loading…';$('recordContent').replaceChildren();$('coverageCards').replaceChildren();$('moreData').hidden=true;$('recordTools').hidden=true;$('importServer').value=row.serverId;
 try{const url=stream==='telemetry'?`/api/admin/recordings/${row.serverId}/${row.id}`:missionRoute();const loaded=await get(url);if(version!==generation)return;summary=loaded;
 const s=stream==='telemetry'?summary:summary.streams[stream];
 $('detailStatus').textContent=stream==='telemetry'?human(summary.status):!s?.available?'No processed data yet':s.droppedRecords||s.sourceComplete===false||!s.allBatchesPresent||row.problems||row.pending||(stream==='session'&&summary.eventSequenceContiguous===false)?'Partial data — inspect Coverage':s.closed?'Closed dataset':'Still open';
 const cards=stream==='telemetry'?[[summary.recordCount,'Records'],[summary.spawnedEntityCount,'Units first recorded'],[summary.droppedRecords,'Dropped'],[summary.closed?'Closed':'Open','Recording']]:[[row.ready,'Processed batches'],[row.pending,'Pending batches'],[row.problems,'Processing problems'],[s?.available?'Received':'Not received',categories[stream][0]]];
 for(const [v,label]of cards){const c=node('div');c.append(node('strong',String(v??'Unknown')),node('span',label));$('coverageCards').append(c);}
 const types=stream==='telemetry'?summary.recordTypes:summary.eventTypes;
 $('eventType').replaceChildren(new Option('All events',''));for(const key of Object.keys(types||{}))$('eventType').add(new Option(`${human(key)} (${types[key]})`,key));
 $('rangeFrom').value=((summary.fromMs??0)/1000).toFixed(1);$('rangeUntil').value=(Math.min(summary.untilMs??60000,(summary.fromMs??0)+60000)/1000).toFixed(1);
 await renderPane();
 }catch(e){if(version===generation){$('detailStatus').textContent=e.message;pane='files';await renderPane();}}
}
async function renderPane(reset=true){if(!selected)return;if(reset)cursor=null;const version=++recordGeneration;const current=generation;$('recordContent').replaceChildren();$('recordStatus').textContent='Loading…';$('moreData').hidden=true;document.querySelectorAll('[data-pane]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pane===pane)));$('recordTools').hidden=pane!=='records'||!['telemetry','session'].includes(stream);$('fromLabel').hidden=$('untilLabel').hidden=stream!=='telemetry';
 try{
 let content,next=null,message='';
 if(pane==='coverage'){
  const target=stream==='telemetry'?summary:summary?.streams?.[stream];
  const wrap=node('div');wrap.append(node('p','No received records does not prove a feature was disabled. Coverage describes this dataset only.'));
  const types=stream==='telemetry'?summary?.recordTypes:summary?.eventTypes;
  if(types&&['telemetry','session'].includes(stream))wrap.append(table(['Recorded event','Count'],Object.entries(types).map(([k,v])=>[human(k),v])));
  if(stream==='telemetry'&&summary?.metadata?.coverage)wrap.append(node('h3','Recorder coverage'),fields(summary.metadata.coverage));
  if(stream!=='telemetry')wrap.append(node('h3','Processing'),fields({ready:selected.ready,pending:selected.pending,problems:selected.problems}));
  if(stream==='session')wrap.append(node('h3','Event coverage'),fields({eventCount:summary?.eventCount,eventSequenceContiguous:summary?.eventSequenceContiguous,recordedJoiners:summary?.recordedJoiners}));
  wrap.append(fields(target));content=wrap;
 }else if(pane==='files'){
  const d=await get(`${datasetRoute()}/batches?after=${cursor??-1}`);next=d.nextAfter;
  content=table(['Revision','Size','Status','Problem',''],d.rows.map(r=>{const a=node('a','Download');a.href=`${datasetRoute()}/batches/${r.revision}`;return[r.revision,bytes(r.bytes),human(r.status),r.error||'—',a];}));message='Original files. Imports are validated and processed through normal intake.';
 }else if(stream==='telemetry'){
  const from=Number($('rangeFrom').value)*1000,until=Number($('rangeUntil').value)*1000;
  if(!Number.isFinite(from)||!Number.isFinite(until)||from<0||until<from||until-from>60000)throw Error('Choose a time window of up to 60 seconds.');
  const d=await get(`/api/admin/recordings/${selected.serverId}/${selected.id}/records?fromMs=${from}&untilMs=${until}&afterSequence=${cursor??0}&limit=100&type=${encodeURIComponent($('eventType').value)}`);next=d.nextAfterSequence;
  content=table(['Time','Event','Unit','Fields'],d.records.map(r=>[time(r.timeMs),human(r.type),r.data?.name||r.data?.entity||'—',expandable(r.data)]));message=`${d.records.length} records in this page${next!==null?' · more to scan':''}.`;
 }else if(stream==='stats'){
  const d=await get(`${missionRoute()}/players${cursor?`?after=${encodeURIComponent(cursor)}`:''}`);next=d.nextAfter;
  content=table(['Player','Kills','Deaths','Shots','Play time','All statistics'],d.players.map(p=>[Object.assign(node('a',p.name||p.identity),{href:'/players?identity='+encodeURIComponent(p.identity)}),p.counters.kills??'Not recorded',p.counters.deaths??'Not recorded',p.counters.shots??'Not recorded',p.counters.playSeconds===undefined?'Not recorded':`${Math.round(p.counters.playSeconds/60)} min`,expandable({...p.counters,identity:p.identity,revision:p.revision})]));message=`${d.players.length} players · latest cumulative totals.`;
 }else if(stream==='session'){
  const d=await get(`${missionRoute()}/events?afterSequence=${cursor??0}${$('eventType').value?'&type='+encodeURIComponent($('eventType').value):''}`);next=d.nextAfterSequence;
  content=table(['Time','Event','Player','Target','Fields'],d.events.map(r=>[`${r.sessionSeconds.toFixed(1)} s`,human(r.type),r.actorName||r.actor||'—',r.targetName||r.target||'—',expandable(r)]));message=`${d.events.length} events in this page.`;
 }else{content=fields(summary?.streams?.history?.metadata);message=summary?.streams?.history?.available?'Latest mission report. Performance values are sampled.':'No processed mission report.';}
 if(version!==recordGeneration||current!==generation)return;
 $('recordContent').append(content);$('recordStatus').textContent=message;cursor=next;$('moreData').hidden=next===null||next===undefined;
 }catch(e){if(version===recordGeneration&&current===generation)$('recordStatus').textContent=e.message;}
}
for(const [key,[title,description]]of Object.entries(categories)){const b=button('',()=>{stream=key;offset=0;selected=null;++generation;++recordGeneration;$('datasetDetail').hidden=true;$('categoryTitle').textContent=title;$('categoryDescription').textContent=description;document.querySelectorAll('[data-stream]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));list();});b.dataset.stream=key;b.setAttribute('aria-pressed',String(key===stream));const count=node('small','Loading…');count.id=`count-${key}`;b.append(node('strong',title),count);$('categories').append(b);}
$('categoryDescription').textContent=categories.telemetry[1];
document.querySelectorAll('[data-pane]').forEach(b=>b.onclick=()=>{pane=b.dataset.pane;renderPane();});
$('readData').onclick=()=>renderPane();$('moreData').onclick=()=>renderPane(false);
$('searchForm').onsubmit=e=>{e.preventDefault();offset=0;list();};$('nextData').onclick=()=>{offset=nextOffset;list();};$('prevData').onclick=()=>{offset=Math.max(0,offset-50);list();};
$('refreshData').onclick=async()=>{overview();list();if(selected){const old=selected,version=generation;try{const data=await get(`/api/admin/explorer?stream=${stream}&search=${encodeURIComponent(old.id)}`);if(version!==generation)return;const row=data.rows.find(r=>r.id===old.id&&r.serverId===old.serverId);if(row)open(row);else{selected=null;++generation;++recordGeneration;$('datasetDetail').hidden=true;}}catch(e){$('detailStatus').textContent=e.message;}}};
$('openImport').onclick=async()=>{$('importStatus').textContent='Loading servers…';$('importDialog').showModal();$('submitImport').disabled=true;try{const servers=await get('/api/admin/explorer/servers');$('importServerChoice').replaceChildren(...servers.map(s=>new Option(s.name,s.id)),new Option('Another server…',''));if(selected&&servers.some(s=>s.id===selected.serverId))$('importServerChoice').value=selected.serverId;$('manualServer').hidden=!!$('importServerChoice').value;$('importStatus').textContent='';}catch(e){$('importStatus').textContent=e.message;$('importServerChoice').replaceChildren(new Option('Enter server ID',''));$('manualServer').hidden=false;}finally{$('submitImport').disabled=false;}};
$('importServerChoice').onchange=()=>{$('manualServer').hidden=!!$('importServerChoice').value;};$('closeImport').onclick=()=>$('importDialog').close();
$('importForm').onsubmit=async e=>{e.preventDefault();const server=$('importServerChoice').value||$('importServer').value.trim();if(!/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(server)){$('importStatus').textContent='Enter a valid server UUID.';return;}const files=[...$('importFiles').files];$('submitImport').disabled=$('closeImport').disabled=true;let imported=0;const failed=[];for(const file of files){try{if(file.size>64*1024*1024)throw Error('File exceeds 64 MB');$('importStatus').textContent=`Importing ${file.name}…`;await mutate(`/api/admin/explorer/import/${server}`,'POST',file);imported++;}catch(e){failed.push(`${file.name}: ${e.message}`);}}$('importStatus').textContent=`${imported} accepted. ${failed.join(' ')} Refresh after processing to see records.`;$('submitImport').disabled=$('closeImport').disabled=false;overview();list();};
$('openRemove').onclick=()=>{if(!selected)return;$('removeScope').textContent=`${categories[stream][0]} · ${selected.id} · ${selected.batches} batches.`;$('removeConfirm').value='';$('removeStatus').textContent='';$('removeDialog').showModal();};$('closeRemove').onclick=()=>$('removeDialog').close();
$('removeForm').onsubmit=async e=>{e.preventDefault();if($('removeConfirm').value!=='REMOVE'||!selected)return;$('submitRemove').disabled=$('closeRemove').disabled=true;try{await mutate(`${datasetRoute()}?expectedBatches=${selected.batches}`,'DELETE');++generation;++recordGeneration;selected=null;$('datasetDetail').hidden=true;$('removeDialog').close();await Promise.all([overview(),list()]);}catch(e){$('removeStatus').textContent=e.message;}finally{$('submitRemove').disabled=$('closeRemove').disabled=false;}};
overview();list();
